/**
 * TradeJournal — Append-only audit log for prediction market signals and paper trades.
 *
 * Cycle 011: Every signal generated and every paper trade executed is logged
 * with full context for compliance, debugging, and performance analysis.
 *
 * Design:
 * - Append-only SQLite table (no updates, no deletes)
 * - Each entry has a type: "signal" | "trade" | "resolve" | "killswitch" | "scan"
 * - Full JSON context stored alongside structured fields
 * - Queryable by time range, type, market, and outcome
 */

export type JournalEntryType = "signal" | "trade" | "resolve" | "killswitch" | "scan" | "error";

export interface JournalEntry {
	id?: number;
	type: JournalEntryType;
	timestamp: number;
	/** ISO date string for easy querying */
	dateKey: string;
	/** Market ID (null for scan-level or killswitch entries) */
	marketId: string | null;
	/** Market question (human readable) */
	question: string | null;
	/** Signal side: "yes" | "no" | null */
	side: string | null;
	/** Key numeric value (EV for signals, size for trades, P&L for resolves) */
	value: number | null;
	/** Full context as JSON */
	context: string;
	/** Pipeline metrics summary (for scan entries) */
	summary: string | null;
}

export interface JournalQuery {
	type?: JournalEntryType;
	marketId?: string;
	since?: number;
	until?: number;
	limit?: number;
	offset?: number;
}

export interface JournalStats {
	totalEntries: number;
	byType: Record<string, number>;
	signalsGenerated: number;
	tradesExecuted: number;
	tradesAccepted: number;
	tradesRejected: number;
	scansCompleted: number;
	errorsLogged: number;
}

type Database = {
	exec(sql: string): void;
	prepare(sql: string): {
		run(...params: unknown[]): { lastInsertRowid: number | bigint };
		get(...params: unknown[]): Record<string, unknown> | undefined;
		all(...params: unknown[]): Record<string, unknown>[];
	};
};

export class TradeJournal {
	private db: Database;

	constructor(db: Database) {
		this.db = db;
		this.initialize();
	}

	private initialize(): void {
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS prediction_journal (
				id INTEGER PRIMARY KEY AUTOINCREMENT,
				type TEXT NOT NULL,
				timestamp INTEGER NOT NULL,
				date_key TEXT NOT NULL,
				market_id TEXT,
				question TEXT,
				side TEXT,
				value REAL,
				context TEXT NOT NULL,
				summary TEXT
			);
			CREATE INDEX IF NOT EXISTS idx_pj_type ON prediction_journal(type);
			CREATE INDEX IF NOT EXISTS idx_pj_timestamp ON prediction_journal(timestamp);
			CREATE INDEX IF NOT EXISTS idx_pj_market ON prediction_journal(market_id);
			CREATE INDEX IF NOT EXISTS idx_pj_date ON prediction_journal(date_key);
		`);
	}

	/** Append a journal entry. Returns the entry ID. */
	append(entry: Omit<JournalEntry, "id">): number {
		const stmt = this.db.prepare(`
			INSERT INTO prediction_journal
				(type, timestamp, date_key, market_id, question, side, value, context, summary)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		`);
		const result = stmt.run(
			entry.type,
			entry.timestamp,
			entry.dateKey,
			entry.marketId,
			entry.question,
			entry.side,
			entry.value,
			entry.context,
			entry.summary,
		);
		return Number(result.lastInsertRowid);
	}

	/** Log a scan cycle result */
	logScan(metrics: {
		marketsReceived: number;
		finalSignals: number;
		totalTimeMs: number;
		passedPreScreen: number;
		passedEnrichment: number;
	}): number {
		const now = Date.now();
		return this.append({
			type: "scan",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: null,
			question: null,
			side: null,
			value: metrics.finalSignals,
			context: JSON.stringify(metrics),
			summary: `${metrics.marketsReceived} markets -> ${metrics.finalSignals} signals in ${metrics.totalTimeMs}ms`,
		});
	}

	/** Log a signal generated by the pipeline */
	logSignal(signal: {
		marketId: string;
		question: string;
		side: string;
		expectedValue: number;
		modelProbability: number;
		marketPrice: number;
		kellySize: number;
		reason: string;
	}): number {
		const now = Date.now();
		return this.append({
			type: "signal",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: signal.marketId,
			question: signal.question,
			side: signal.side,
			value: signal.expectedValue,
			context: JSON.stringify(signal),
			summary: `${signal.side.toUpperCase()} EV=${(signal.expectedValue * 100).toFixed(1)}% model=${(signal.modelProbability * 100).toFixed(1)}% vs market=${(signal.marketPrice * 100).toFixed(1)}%`,
		});
	}

	/** Log a paper trade execution attempt */
	logTrade(trade: {
		tradeId?: string;
		marketId: string;
		question: string;
		side: string;
		size: number;
		entryPrice: number;
		accepted: boolean;
		reason: string;
	}): number {
		const now = Date.now();
		return this.append({
			type: "trade",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: trade.marketId,
			question: trade.question,
			side: trade.side,
			value: trade.accepted ? trade.size : 0,
			context: JSON.stringify(trade),
			summary: trade.accepted
				? `EXECUTED ${trade.side.toUpperCase()} $${trade.size.toFixed(2)} @ ${trade.entryPrice.toFixed(3)} [${trade.tradeId}]`
				: `REJECTED: ${trade.reason}`,
		});
	}

	/** Log a market resolution */
	logResolve(resolve: {
		marketId: string;
		question: string;
		outcome: 0 | 1;
		tradesResolved: number;
		totalPnl: number;
	}): number {
		const now = Date.now();
		return this.append({
			type: "resolve",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: resolve.marketId,
			question: resolve.question,
			side: resolve.outcome === 1 ? "yes" : "no",
			value: resolve.totalPnl,
			context: JSON.stringify(resolve),
			summary: `Outcome=${resolve.outcome === 1 ? "YES" : "NO"} trades=${resolve.tradesResolved} P&L=$${resolve.totalPnl.toFixed(2)}`,
		});
	}

	/** Log a kill switch event */
	logKillSwitch(event: {
		action: "activate" | "deactivate";
		level: string;
		reason: string;
	}): number {
		const now = Date.now();
		return this.append({
			type: "killswitch",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: null,
			question: null,
			side: null,
			value: null,
			context: JSON.stringify(event),
			summary: `${event.action.toUpperCase()} level=${event.level} reason=${event.reason}`,
		});
	}

	/** Log an error */
	logError(error: {
		stage: string;
		message: string;
		marketId?: string;
		stack?: string;
	}): number {
		const now = Date.now();
		return this.append({
			type: "error",
			timestamp: now,
			dateKey: new Date(now).toISOString().split("T")[0],
			marketId: error.marketId ?? null,
			question: null,
			side: null,
			value: null,
			context: JSON.stringify(error),
			summary: `[${error.stage}] ${error.message}`,
		});
	}

	/** Query journal entries */
	query(opts: JournalQuery = {}): JournalEntry[] {
		const conditions: string[] = [];
		const params: unknown[] = [];

		if (opts.type) {
			conditions.push("type = ?");
			params.push(opts.type);
		}
		if (opts.marketId) {
			conditions.push("market_id = ?");
			params.push(opts.marketId);
		}
		if (opts.since) {
			conditions.push("timestamp >= ?");
			params.push(opts.since);
		}
		if (opts.until) {
			conditions.push("timestamp <= ?");
			params.push(opts.until);
		}

		const where = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
		const limit = opts.limit ?? 100;
		const offset = opts.offset ?? 0;

		const sql = `SELECT * FROM prediction_journal ${where} ORDER BY timestamp DESC LIMIT ? OFFSET ?`;
		params.push(limit, offset);

		const rows = this.db.prepare(sql).all(...params);
		return rows.map(rowToEntry);
	}

	/** Get recent entries (shorthand) */
	recent(limit = 50): JournalEntry[] {
		return this.query({ limit });
	}

	/** Get journal stats */
	stats(): JournalStats {
		const totalRow = this.db.prepare("SELECT COUNT(*) as cnt FROM prediction_journal").get() as { cnt: number };
		const typeRows = this.db.prepare(
			"SELECT type, COUNT(*) as cnt FROM prediction_journal GROUP BY type",
		).all() as Array<{ type: string; cnt: number }>;

		const byType: Record<string, number> = {};
		for (const row of typeRows) {
			byType[row.type] = row.cnt;
		}

		// Count accepted vs rejected trades
		const acceptedRow = this.db.prepare(
			"SELECT COUNT(*) as cnt FROM prediction_journal WHERE type = 'trade' AND value > 0",
		).get() as { cnt: number };
		const rejectedRow = this.db.prepare(
			"SELECT COUNT(*) as cnt FROM prediction_journal WHERE type = 'trade' AND (value = 0 OR value IS NULL)",
		).get() as { cnt: number };

		return {
			totalEntries: totalRow.cnt,
			byType,
			signalsGenerated: byType["signal"] ?? 0,
			tradesExecuted: byType["trade"] ?? 0,
			tradesAccepted: acceptedRow.cnt,
			tradesRejected: rejectedRow.cnt,
			scansCompleted: byType["scan"] ?? 0,
			errorsLogged: byType["error"] ?? 0,
		};
	}

	/** Get entries count */
	count(): number {
		const row = this.db.prepare("SELECT COUNT(*) as cnt FROM prediction_journal").get() as { cnt: number };
		return row.cnt;
	}

	/**
	 * Delete journal entries older than the specified number of days.
	 * Returns the number of entries pruned.
	 * @param retentionDays - Keep entries newer than this (default: 90)
	 */
	prune(retentionDays = 90): number {
		const cutoff = Date.now() - retentionDays * 24 * 60 * 60 * 1000;
		const before = this.count();
		this.db.prepare("DELETE FROM prediction_journal WHERE timestamp < ?").run(cutoff);
		const after = this.count();
		return before - after;
	}
}

// ── Helpers ──

function rowToEntry(row: Record<string, unknown>): JournalEntry {
	return {
		id: row.id as number,
		type: row.type as JournalEntryType,
		timestamp: row.timestamp as number,
		dateKey: row.date_key as string,
		marketId: row.market_id as string | null,
		question: row.question as string | null,
		side: row.side as string | null,
		value: row.value as number | null,
		context: row.context as string,
		summary: row.summary as string | null,
	};
}
